package com.smartsociety.platform.notice; import com.smartsociety.platform.auth.*;import com.smartsociety.platform.common.*;import com.smartsociety.platform.notification.NotificationService;import com.smartsociety.platform.security.SecurityUser;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class NoticeService {final NoticeRepository repo;final UserRepository users;final NotificationService notifications;public NoticeService(NoticeRepository r,UserRepository u,NotificationService n){repo=r;users=u;notifications=n;}@Transactional public NoticeDtos.Response create(NoticeDtos.Request r,SecurityUser a){var n=new Notice();n.setAuthor(a.user());n.setTitle(r.title().trim());n.setBody(r.body().trim());n.setImportant(r.important());n.setPublished(r.published());repo.save(n);if(n.isPublished()&&n.isImportant())users.findAll().stream().filter(User::isEnabled).forEach(u->notifications.importantNotice(u.getEmail(),n.getTitle(),n.getBody()));return map(n);}@Transactional public NoticeDtos.Response update(java.util.UUID id, NoticeDtos.Request r, SecurityUser a){var n=repo.findById(id).orElseThrow(()->new com.smartsociety.platform.common.DomainException(org.springframework.http.HttpStatus.NOT_FOUND,"Notice not found"));n.setTitle(r.title().trim());n.setBody(r.body().trim());n.setImportant(r.important());n.setPublished(r.published());return map(n);}@Transactional public void archive(java.util.UUID id){var n=repo.findById(id).orElseThrow(()->new com.smartsociety.platform.common.DomainException(org.springframework.http.HttpStatus.NOT_FOUND,"Notice not found"));n.setPublished(false);}@Transactional(readOnly=true) public List<NoticeDtos.Response> published(){return repo.findByPublishedTrueOrderByImportantDescPublishedAtDesc().stream().map(this::map).toList();}private NoticeDtos.Response map(Notice n){return new NoticeDtos.Response(n.getId(),n.getTitle(),n.getBody(),n.isImportant(),n.isPublished(),n.getCreatedAt());}}
